import{c as t,Q as a,j as d,m as i}from"./chunks/framework.g_l1frA7.js";const g=JSON.parse('{"title":"API & RPC","description":"","frontmatter":{},"headers":[],"relativePath":"developers/api.md","filePath":"developers/api.md","lastUpdated":null}'),s={name:"developers/api.md"};function o(n,e,c,p,r,h){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="api-rpc" tabindex="-1">API &amp; RPC <a class="header-anchor" href="#api-rpc" aria-label="Permalink to &quot;API &amp; RPC&quot;">​</a></h1><p>FinSight exposes a typed RPC surface described by an OpenAPI spec that is generated at build time, not hand-written.</p><h2 id="routes" tabindex="-1">Routes <a class="header-anchor" href="#routes" aria-label="Permalink to &quot;Routes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/rpc/{cmd}</code></td><td>Authenticated RPC; body is camelCase DTO</td></tr><tr><td><code>GET</code></td><td><code>/api/events</code></td><td>SSE stream for Copilot + query invalidations</td></tr><tr><td><code>GET</code></td><td><code>/api/openapi.json</code></td><td>Generated spec</td></tr><tr><td><code>POST</code></td><td><code>/api/uploads/*</code></td><td>Authenticated CSV staging</td></tr><tr><td><code>*</code></td><td><code>/</code></td><td>Serves <code>ui/dist</code> (SPA fallback)</td></tr></tbody></table><p>Every RPC response is enveloped as <code>Result&lt;T, AppError&gt;</code>; <code>401</code> surfaces as <code>FINSIGHT_AUTH_REQUIRED</code> on the client.</p><h2 id="adding-or-changing-a-command" tabindex="-1">Adding or changing a command <a class="header-anchor" href="#adding-or-changing-a-command" aria-label="Permalink to &quot;Adding or changing a command&quot;">​</a></h2><ol><li>Implement <code>pub async fn my_cmd(state: &amp;ApiState, ...)</code> in <code>crates/finsight-api/src/commands/</code>.</li><li>Add <code>#[utoipa::path]</code> + <code>ToSchema</code> on handler/DTOs; keep <code>crates/finsight-openapi/src/lib.rs::COMMANDS</code> sorted and identical to <code>crates/finsight-server/src/dispatch.rs::SUPPORTED</code>.</li><li>Add the dispatcher arm in <code>dispatch.rs</code> via <code>rpc_routes!(api, events, cmd, p, c: …)</code> — use <code>arg(&amp;p, &quot;camelCase&quot;)</code>.</li><li>Run <code>pnpm openapi</code> and verify:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> finsight-server</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> parity</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> finsight-openapi</span></span></code></pre></div><ol start="5"><li>If the DTO shape changed, <code>pnpm typecheck</code> fails until hooks in <code>ui/src/api/hooks</code> are updated.</li></ol><h2 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h2><p>Generated contract: <code>ui/src/api/openapi.ts</code> (from <code>openapi.json</code> via <code>openapi-typescript</code>).</p><p>Typed transport: <code>ui/src/api/openapiClient.ts</code> (<code>openapi-fetch</code>) — every hook imports <code>api</code> from there. No second transport exists. See <a href="/FinSight/developers/bindings">OpenAPI Bindings</a>.</p><p>Next: <a href="/FinSight/developers/frontend">Frontend</a>.</p>`,13)])])}const m=t(s,[["render",o]]);export{g as __pageData,m as default};
